{
  "outcome": "escalate",
  "rationale": "We are escalating this claim because the total amount of loss reaches the high-value referral threshold. This decision is governed by clause STD-6.1, which mandates review for claims at or above $30,000.00.",
  "citations": [
    {
      "clause_id": "STD-6.1",
      "quote": "Any claim where the amount of loss is at or above $30,000 must be escalated to a senior adjuster for review before any payment is authorized, even if no exclusion appears to apply."
    }
  ]
}
